def require(condition: bool, message: str) -> None:
    if not condition:
        raise AssertionError(message)

def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def write_exclusive(path: Path, data: bytes, mode: int = 0o640) -> None:
    descriptor = os.open(
        path,
        os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
        mode,
    )
    with os.fdopen(descriptor, "wb", closefd=True) as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())

def mkdir_exclusive(path: Path, mode: int = 0o750) -> None:
    os.mkdir(path, mode)

def regular_nonsymlink(path: Path, label: str) -> os.stat_result:
    item = path.lstat()
    require(stat.S_ISREG(item.st_mode), f"{label}_NOT_REGULAR")
    require(not stat.S_ISLNK(item.st_mode), f"{label}_SYMLINK")
    return item

def metadata(path: Path, source_path: str, snapshot_relative: str) -> dict[str, Any]:
    item = regular_nonsymlink(path, source_path)
    return {
        "source_path": source_path,
        "snapshot_relative_path": snapshot_relative,
        "sha256": sha256(path),
        "size_bytes": item.st_size,
        "source_mode": f"{stat.S_IMODE(item.st_mode):04o}",
        "source_uid": item.st_uid,
        "source_gid": item.st_gid,
        "source_owner": pwd.getpwuid(item.st_uid).pw_name,
        "source_group": grp.getgrgid(item.st_gid).gr_name,
    }

def copy_exclusive(source: Path, destination: Path) -> None:
    regular_nonsymlink(source, str(source))
    write_exclusive(destination, source.read_bytes())

def scan(root: Path) -> tuple[set[str], set[str], int, int]:
    files: set[str] = set()
    directories: set[str] = set()
    links = 0
    other = 0
    for path in root.rglob("*"):
        item = path.lstat()
        relative = path.relative_to(root).as_posix()
        if stat.S_ISLNK(item.st_mode):
            links += 1
        elif stat.S_ISREG(item.st_mode):
            files.add(relative)
        elif stat.S_ISDIR(item.st_mode):
            directories.add(relative)
        else:
            other += 1
    return files, directories, links, other

